PRAGMA page_size=1024; BEGIN; CREATE TABLE t4(rowid INTEGER PRIMARY KEY,i INTEGER,t TEXT); WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<9999) INSERT INTO t4(rowid,i,t) SELECT NULL,n,printf('number %d',n) FROM seq ORDER BY n; UPDATE t4 SET i=rowid*2,t=printf('number %d',rowid*2) WHERE rowid<20000 AND (rowid%2)=1; COMMIT;